"use strict";
// The binding of the island module is used while this module evaluates
// and written again only inside a function, so it is not the module at
// every use. The build learns that the uses cannot stay native in the
// round that first runs the required package in the island; this package
// joins the island in the same build.
var pantry = require("pantry");

var salt = pantry.find("salt").grams;

exports.grams = function grams(name) {
  return salt + pantry.find(name).grams;
};
exports.empty = function empty() {
  pantry = {
    find: function () {
      return { label: "none", grams: 0 };
    },
  };
};
